<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login(); $pageTitle='Point of Sale';
$products=$pdo->query('SELECT id,name,sku,unit,selling_price,stock_qty FROM products WHERE active=1 AND stock_qty>0 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$cart=$_POST['cart']??[];$cash=(float)($_POST['cash_received']??0);$discount=(float)($_POST['discount']??0);
 try{
  if(!is_array($cart)||!$cart)throw new RuntimeException('Add at least one product to the cart.');
  $pdo->beginTransaction();$items=[];$subtotal=0;
  $q=$pdo->prepare('SELECT id,name,unit,cost_price,selling_price,stock_qty FROM products WHERE id=? AND active=1 FOR UPDATE');
  foreach($cart as $pid=>$qtyRaw){$pid=(int)$pid;$qty=(float)$qtyRaw;if($qty<=0)continue;$q->execute([$pid]);$p=$q->fetch();if(!$p)throw new RuntimeException('A selected product is no longer available.');if($qty>(float)$p['stock_qty'])throw new RuntimeException('Not enough stock for '.$p['name'].'. Available: '.$p['stock_qty']);$line=round($qty*(float)$p['selling_price'],2);$subtotal+=$line;$items[]=['product'=>$p,'qty'=>$qty,'subtotal'=>$line];}
  if(!$items)throw new RuntimeException('Add at least one valid product.');
  if($discount<0||$discount>$subtotal)throw new RuntimeException('Discount must be between ₱0 and the subtotal.');
  $total=round($subtotal-$discount,2);if($cash<$total)throw new RuntimeException('Cash received must cover the total amount.');
  $transactionNo='SS'.date('ymdHis').str_pad((string)random_int(0,999),3,'0',STR_PAD_LEFT);
  $s=$pdo->prepare("INSERT INTO sales(transaction_no,cashier_id,subtotal,discount,total_amount,cash_received,change_amount,status) VALUES(?,?,?,?,?,?,?,'completed')");
  $s->execute([$transactionNo,$_SESSION['user_id'],$subtotal,$discount,$total,$cash,round($cash-$total,2)]);$saleId=(int)$pdo->lastInsertId();
  foreach($items as $it){$p=$it['product'];$qty=$it['qty'];$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,unit_cost,subtotal) VALUES(?,?,?,?,?,?,?)')->execute([$saleId,$p['id'],$p['name'],$qty,$p['selling_price'],$p['cost_price'],$it['subtotal']]);$pdo->prepare('UPDATE products SET stock_qty=stock_qty-? WHERE id=?')->execute([$qty,$p['id']]);$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,movement_type,quantity_change,reference_type,reference_id,notes) VALUES(?,?,'sale',?,'sale',?,'POS sale')")->execute([$p['id'],$_SESSION['user_id'],-$qty,$saleId]);}
  $pdo->commit();log_action($pdo,'create','sale',$saleId,$transactionNo);header('Location: sales.php?receipt='.$saleId);exit;
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex instanceof PDOException?'Sale could not be saved. Please retry.':$ex->getMessage();}
}
require __DIR__.'/includes/header.php';
?>
<div class="pos-layout"><section class="panel pos-products"><div class="panel-heading"><div><h3>Choose products</h3><p>Tap a product to add it to the cart.</p></div><span class="subtle-tag"><?= count($products) ?> available</span></div><input id="productSearch" class="search-wide" placeholder="Search products by name or SKU…"><div class="pos-product-grid" id="posProductGrid"><?php foreach($products as $p): ?><button type="button" class="pos-product" data-id="<?= $p['id'] ?>" data-name="<?= e($p['name']) ?>" data-sku="<?= e($p['sku']??'') ?>" data-price="<?= e((string)$p['selling_price']) ?>" data-stock="<?= e((string)$p['stock_qty']) ?>" data-unit="<?= e($p['unit']) ?>"><span class="pos-product-icon"><?= e(strtoupper(substr($p['name'],0,1))) ?></span><strong><?= e($p['name']) ?></strong><small><?= money($p['selling_price']) ?> / <?= e($p['unit']) ?></small><span class="stock-hint"><?= e((string)$p['stock_qty']) ?> <?= e($p['unit']) ?> available</span></button><?php endforeach; ?></div><p id="noProducts" class="muted hidden">No matching products found.</p></section>
<section class="panel cart-panel"><div class="panel-heading"><div><h3>Current sale</h3><p>Review items before checkout.</p></div><button type="button" id="clearCart" class="btn ghost small">Clear</button></div><?php if(!empty($error)): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="post" id="checkoutForm"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div id="cartItems" class="cart-items"><div class="empty-state compact"><div>＋</div><strong>Your cart is empty</strong><p>Select products to start a sale.</p></div></div><div id="hiddenCart"></div><div class="cart-summary"><div><span>Subtotal</span><strong id="subtotalDisplay">₱0.00</strong></div><div class="discount-line"><label for="discount">Discount (₱)</label><input id="discount" name="discount" type="number" min="0" step="0.01" value="0"></div><div class="total-line"><span>Total due</span><strong id="totalDisplay">₱0.00</strong></div><label for="cashReceived">Cash received (₱)</label><input id="cashReceived" name="cash_received" type="number" min="0" step="0.01" required placeholder="Enter amount received"><div class="change-line"><span>Change</span><strong id="changeDisplay">₱0.00</strong></div><button class="btn primary full checkout-btn" type="submit">Complete sale <span>→</span></button><p class="form-help center">Stock is deducted only after the sale is saved successfully.</p></div></form></section></div>
<script src="assets/js/pos.js"></script>
<?php require __DIR__.'/includes/footer.php'; ?>
